package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/store"
)

// TestSweepRetention pins the retention pass end to end (fix-reheal-eviction
// task 2.1, Interface 2 + D3): the dual anchor is exact — a stale directory
// reclaims only once it is past the grace on BOTH its own mtime and its item
// row's updated_at — the document-named build is never a victim, orphans are
// judged on mtime alone, an unreadable row skips its item before any eviction
// decision, and every reclamation rides evictDir's move-aside-then-delete
// vocabulary. The clock is never slept: the grace rides the signature as a
// parameter (the budgetBytes pattern), and the tests age the anchors
// directly — os.Chtimes backdates directory mtimes, a raw UPDATE backdates
// items.updated_at (PutItem always stamps now, so the row anchor's age has no
// store-API route; the second connection sits on the same WAL database while
// the store is idle). Every case that turns on grace runs against the real
// locked retentionGrace — 2h-old anchors are past it, fresh ones are not.
func TestSweepRetention(t *testing.T) {
	// retentionSeed seeds one live item per docs key and returns the store,
	// its context, an empty artifact root, and the db file path (for
	// retentionBackdate).
	retentionSeed := func(t *testing.T, docs map[string]map[string]any) (*store.Store, context.Context, string, string) {
		t.Helper()
		ctx := context.Background()
		dbPath := filepath.Join(t.TempDir(), "retention.db")
		st, err := store.Open(ctx, dbPath)
		if err != nil {
			t.Fatalf("store.Open: %v", err)
		}
		t.Cleanup(func() { _ = st.Close() })
		libID, err := st.CreateLibrary(ctx, "tv", "/media/retention", "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		for id, doc := range docs {
			raw, err := json.Marshal(doc)
			if err != nil {
				t.Fatalf("marshal doc %s: %v", id, err)
			}
			if err := st.PutItem(ctx, store.Item{
				ID: id, ModuleID: "tv", LibraryID: libID, FileID: id,
				RelativePath: id + ".mkv", MediaType: "tv",
				Document: raw, SchemaVersion: 1,
			}); err != nil {
				t.Fatalf("PutItem %s: %v", id, err)
			}
		}
		return st, ctx, filepath.Join(t.TempDir(), "streams"), dbPath
	}

	// retentionBuild lays down one build directory (a segment inside, so the
	// tree is real) and backdates its mtime by age (0 keeps it fresh).
	retentionBuild := func(t *testing.T, root, itemID, name string, age time.Duration) string {
		t.Helper()
		p := filepath.Join(root, itemID, name)
		if err := os.MkdirAll(p, 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", p, err)
		}
		if err := os.WriteFile(filepath.Join(p, "seg0.ts"), []byte("segment"), 0o644); err != nil {
			t.Fatalf("write segment in %s: %v", p, err)
		}
		if age > 0 {
			old := time.Now().Add(-age)
			if err := os.Chtimes(p, old, old); err != nil {
				t.Fatalf("chtimes %s: %v", p, err)
			}
		}
		return p
	}

	// retentionBackdate rewrites one item row's updated_at age seconds into
	// the past — the row anchor's age (RFC3339Nano, the store's stamp
	// format).
	retentionBackdate := func(t *testing.T, dbPath, itemID string, age time.Duration) {
		t.Helper()
		db, err := sql.Open("sqlite", dbPath)
		if err != nil {
			t.Fatalf("open db for backdate: %v", err)
		}
		defer db.Close()
		stamp := time.Now().Add(-age).UTC().Format(time.RFC3339Nano)
		res, err := db.ExecContext(context.Background(),
			`UPDATE items SET updated_at = ? WHERE id = ?`, stamp, itemID)
		if err != nil {
			t.Fatalf("backdate updated_at: %v", err)
		}
		if n, _ := res.RowsAffected(); n != 1 {
			t.Fatalf("backdate updated_at: %d rows affected, want 1", n)
		}
	}

	// retentionDoc builds an item document whose streams namespace carries
	// the given packaging state and (optional) build nonce.
	retentionDoc := func(state, nonce string) map[string]any {
		streams := map[string]any{"state": state}
		if nonce != "" {
			streams["nonce"] = nonce
		}
		return map[string]any{"streams": streams}
	}

	old := 2 * time.Hour // comfortably past the 10-minute grace

	t.Run("just superseded survives one grace", func(t *testing.T) {
		// Old-mtime directory, fresh row: the mtime anchor is past the
		// grace but the row anchor is not — the just-superseded build a
		// live session still holds URLs for must survive (D3).
		st, ctx, root, _ := retentionSeed(t, map[string]map[string]any{
			"itm_a": retentionDoc("complete", "cur1"),
		})
		retentionBuild(t, root, "itm_a", "cur1", 0)
		retentionBuild(t, root, "itm_a", "old1", old)
		sweepRetention(ctx, st, root, retentionGrace)
		for _, name := range []string{"cur1", "old1"} {
			if _, err := os.Stat(filepath.Join(root, "itm_a", name)); err != nil {
				t.Fatalf("superseded build %s was reclaimed before the row anchor aged past the grace: %v", name, err)
			}
		}
	})

	t.Run("fresh directory over an old document survives", func(t *testing.T) {
		// Fresh-mtime directory, old row: the in-flight pack shape (D3) —
		// the first pack's row was last written at scan time, its staging
		// is minutes old — must survive on the mtime anchor alone.
		st, ctx, root, dbPath := retentionSeed(t, map[string]map[string]any{
			"itm_b": retentionDoc("complete", "cur1"),
		})
		retentionBuild(t, root, "itm_b", "cur1", 0)
		retentionBuild(t, root, "itm_b", ".tmp-b1", 0)
		retentionBackdate(t, dbPath, "itm_b", old)
		sweepRetention(ctx, st, root, retentionGrace)
		for _, name := range []string{"cur1", ".tmp-b1"} {
			if _, err := os.Stat(filepath.Join(root, "itm_b", name)); err != nil {
				t.Fatalf("in-flight build %s was reclaimed before its mtime aged past the grace: %v", name, err)
			}
		}
	})

	t.Run("past grace on both anchors reclaims via move-aside", func(t *testing.T) {
		// Both anchors past the grace: the superseded build is gone, moved
		// aside then deleted (the evictDir vocabulary — no .trash leftover),
		// while the document-named build survives untouched.
		st, ctx, root, dbPath := retentionSeed(t, map[string]map[string]any{
			"itm_c": retentionDoc("complete", "cur1"),
		})
		retentionBuild(t, root, "itm_c", "cur1", old)
		retentionBuild(t, root, "itm_c", "old1", old)
		retentionBackdate(t, dbPath, "itm_c", old)
		sweepRetention(ctx, st, root, retentionGrace)
		if _, err := os.Stat(filepath.Join(root, "itm_c", "old1")); !os.IsNotExist(err) {
			t.Fatalf("superseded build past both anchors still exists (stat err %v)", err)
		}
		if _, err := os.Stat(filepath.Join(root, "itm_c", "old1.trash")); !os.IsNotExist(err) {
			t.Fatalf("evictDir move-aside leftover .trash sibling still exists (stat err %v)", err)
		}
		if _, err := os.Stat(filepath.Join(root, "itm_c", "cur1")); err != nil {
			t.Fatalf("document-named build was reclaimed: %v", err)
		}
	})

	t.Run("document-named build spared in every packaging state", func(t *testing.T) {
		// A complete doc names its build — that directory survives even
		// fully past the grace; none/failed/partial docs name nothing, so
		// every directory under them is stale and past-grace ones reclaim.
		st, ctx, root, dbPath := retentionSeed(t, map[string]map[string]any{
			"itm_c":  retentionDoc("complete", "cur1"),
			"itm_n":  retentionDoc("none", ""),
			"itm_f":  retentionDoc("failed", ""),
			"itm_p":  retentionDoc("partial", ""),
			"itm_ud": retentionDoc("", ""), // no streams namespace at all
		})
		retentionBuild(t, root, "itm_c", "cur1", old)
		for _, item := range []string{"itm_n", "itm_f", "itm_p", "itm_ud"} {
			retentionBuild(t, root, item, "stray", old)
			retentionBackdate(t, dbPath, item, old)
		}
		retentionBackdate(t, dbPath, "itm_c", old)
		sweepRetention(ctx, st, root, retentionGrace)
		if _, err := os.Stat(filepath.Join(root, "itm_c", "cur1")); err != nil {
			t.Fatalf("document-named build was reclaimed: %v", err)
		}
		for _, item := range []string{"itm_n", "itm_f", "itm_p", "itm_ud"} {
			if _, err := os.Stat(filepath.Join(root, item, "stray")); !os.IsNotExist(err) {
				t.Fatalf("%s: nameless doc left its stale directory unreclaimed (stat err %v)", item, err)
			}
		}
	})

	t.Run("fresh staging survives, stale staging and stale trash reclaim", func(t *testing.T) {
		// No prefix carve-out: fresh .tmp- staging survives on its mtime
		// anchor (in-flight pack), while stale staging and a stale .trash
		// sibling (crash hygiene) reclaim like any other stale directory.
		st, ctx, root, dbPath := retentionSeed(t, map[string]map[string]any{
			"itm_d": retentionDoc("complete", "cur1"),
		})
		retentionBuild(t, root, "itm_d", "cur1", 0)
		retentionBuild(t, root, "itm_d", ".tmp-b1", 0)
		retentionBuild(t, root, "itm_d", ".tmp-b2", old)
		retentionBuild(t, root, "itm_d", "old1.trash", old)
		retentionBackdate(t, dbPath, "itm_d", old)
		sweepRetention(ctx, st, root, retentionGrace)
		if _, err := os.Stat(filepath.Join(root, "itm_d", ".tmp-b1")); err != nil {
			t.Fatalf("fresh staging was reclaimed before its mtime aged past the grace: %v", err)
		}
		for _, name := range []string{".tmp-b2", "old1.trash"} {
			if _, err := os.Stat(filepath.Join(root, "itm_d", name)); !os.IsNotExist(err) {
				t.Fatalf("stale %s still exists (stat err %v)", name, err)
			}
		}
		if _, err := os.Stat(filepath.Join(root, "itm_d", "cur1")); err != nil {
			t.Fatalf("document-named build was reclaimed: %v", err)
		}
	})

	t.Run("orphan directories judged on mtime alone", func(t *testing.T) {
		// No row at all (ErrNoRows — orphaned by a moved/deleted library
		// file): every directory is stale and the mtime is the only anchor.
		st, ctx, root, _ := retentionSeed(t, map[string]map[string]any{})
		retentionBuild(t, root, "itm_orph", "stale1", old)
		retentionBuild(t, root, "itm_orph", "fresh1", 0)
		sweepRetention(ctx, st, root, retentionGrace)
		if _, err := os.Stat(filepath.Join(root, "itm_orph", "stale1")); !os.IsNotExist(err) {
			t.Fatalf("orphan directory past its mtime grace still exists (stat err %v)", err)
		}
		if _, err := os.Stat(filepath.Join(root, "itm_orph", "fresh1")); err != nil {
			t.Fatalf("orphan directory within its mtime grace was reclaimed: %v", err)
		}
	})

	t.Run("unreadable row skips the item", func(t *testing.T) {
		// A read error that is not ErrNoRows (here: the store is closed)
		// must skip the item BEFORE any eviction decision — never evict
		// blind (the sweepBudget precedent). Nothing under the item moves,
		// whatever its age.
		st, ctx, root, _ := retentionSeed(t, map[string]map[string]any{
			"itm_e": retentionDoc("complete", "cur1"),
		})
		retentionBuild(t, root, "itm_e", "cur1", 0)
		retentionBuild(t, root, "itm_e", "old1", old)
		if err := st.Close(); err != nil {
			t.Fatalf("close store: %v", err)
		}
		sweepRetention(ctx, st, root, retentionGrace)
		for _, name := range []string{"cur1", "old1"} {
			if _, err := os.Stat(filepath.Join(root, "itm_e", name)); err != nil {
				t.Fatalf("unreadable-row item was not skipped — %s missing: %v", name, err)
			}
		}
	})
}

// budgetItem is one seeded row for the budget sweep tests: its document and
// (optionally) a non-default row status.
type budgetItem struct {
	doc    map[string]any
	status string // "" = the store default
}

// TestSweepBudget pins the budget sweep's stale-flag computation
// (fix-reheal-eviction task 2.2, Interface 3 + D4): sweepBudget marks a
// directory stale when the item document does not name it — a complete doc
// names its current nonce, so only its sibling directories are stale; a
// none/failed (nameless) doc leaves every directory stale; an orphan row
// (no item) and a deleted-status row mark EVERY directory stale. The flags
// are pinned behaviorally, through eviction outcomes: stale directories
// reclaim before any current build whatever the recency, so each case sets
// a budget that is met exactly by the stale set — the current build must
// survive, and for the complete doc the post-eviction unpublish must no-op
// on the stale nonce. No watch recency is seeded except the deleted-row
// case, whose fresh progress stamp is the discriminator: without the
// all-stale rule the unwatched current build would sort first on recency.
func TestSweepBudget(t *testing.T) {
	// budgetSeed seeds one live item per item spec and returns the store,
	// its context, and an empty artifact root.
	budgetSeed := func(t *testing.T, items map[string]budgetItem) (*store.Store, context.Context, string) {
		t.Helper()
		ctx := context.Background()
		st, err := store.Open(ctx, filepath.Join(t.TempDir(), "budget.db"))
		if err != nil {
			t.Fatalf("store.Open: %v", err)
		}
		t.Cleanup(func() { _ = st.Close() })
		libID, err := st.CreateLibrary(ctx, "tv", "/media/budget", "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		for id, it := range items {
			raw, err := json.Marshal(it.doc)
			if err != nil {
				t.Fatalf("marshal doc %s: %v", id, err)
			}
			if err := st.PutItem(ctx, store.Item{
				ID: id, ModuleID: "tv", LibraryID: libID, FileID: id,
				RelativePath: id + ".mkv", MediaType: "tv",
				Document: raw, SchemaVersion: 1, Status: it.status,
			}); err != nil {
				t.Fatalf("PutItem %s: %v", id, err)
			}
		}
		return st, ctx, filepath.Join(t.TempDir(), "streams")
	}

	// budgetBuild lays down one build directory (a segment inside, so its
	// size is real and identical across directories).
	budgetBuild := func(t *testing.T, root, itemID, name string) string {
		t.Helper()
		p := filepath.Join(root, itemID, name)
		if err := os.MkdirAll(p, 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", p, err)
		}
		if err := os.WriteFile(filepath.Join(p, "seg0.ts"), []byte("segment"), 0o644); err != nil {
			t.Fatalf("write segment in %s: %v", p, err)
		}
		return p
	}

	// budgetDoc builds an item document whose streams namespace carries the
	// given packaging state and (optional) build nonce.
	budgetDoc := func(state, nonce string) map[string]any {
		streams := map[string]any{"state": state}
		if nonce != "" {
			streams["nonce"] = nonce
		}
		return map[string]any{"streams": streams}
	}

	t.Run("complete doc: stale siblings reclaim before the current build", func(t *testing.T) {
		// The doc names cur1 — only old1 is stale. The budget is met by
		// reclaiming exactly one directory: stale-first must pick old1 (the
		// path tie-break alone would pick cur1, the published build).
		st, ctx, root := budgetSeed(t, map[string]budgetItem{
			"itm_a": {doc: budgetDoc("complete", "cur1")},
		})
		cur := budgetBuild(t, root, "itm_a", "cur1")
		oldDir := budgetBuild(t, root, "itm_a", "old1")
		sweepBudget(ctx, st, root, dirSize(cur), nil, nil)
		if _, err := os.Stat(oldDir); !os.IsNotExist(err) {
			t.Fatalf("stale sibling still exists after the budget was met from it alone (stat err %v)", err)
		}
		if _, err := os.Stat(cur); err != nil {
			t.Fatalf("document-named build was evicted: %v", err)
		}
		row, err := st.GetItem(ctx, "itm_a", access.System())
		if err != nil {
			t.Fatalf("GetItem after sweep: %v", err)
		}
		streams, _ := decodeItemDoc(row.Document)["streams"].(map[string]any)
		if state, _ := streams["state"].(string); state != "complete" {
			t.Fatalf("evicting a stale nonce unpublished the doc: state %q", state)
		}
		if nonce, _ := streams["nonce"].(string); nonce != "cur1" {
			t.Fatalf("evicting a stale nonce moved the doc nonce: %q", nonce)
		}
	})

	t.Run("nameless docs leave every directory stale", func(t *testing.T) {
		// none/failed docs name no build: both their directories are stale
		// and reclaim before the live item's current build, despite the
		// path order that would otherwise put aaa1 first.
		st, ctx, root := budgetSeed(t, map[string]budgetItem{
			"itm_none": {doc: budgetDoc("none", "")},
			"itm_fail": {doc: budgetDoc("failed", "")},
			"itm_cur":  {doc: budgetDoc("complete", "aaa1")},
		})
		cur := budgetBuild(t, root, "itm_cur", "aaa1")
		noneDir := budgetBuild(t, root, "itm_none", "zzn1")
		failDir := budgetBuild(t, root, "itm_fail", "zzf1")
		sweepBudget(ctx, st, root, dirSize(cur), nil, nil)
		for _, p := range []string{noneDir, failDir} {
			if _, err := os.Stat(p); !os.IsNotExist(err) {
				t.Fatalf("nameless-doc directory %s still exists after the budget was met from the stale set (stat err %v)", p, err)
			}
		}
		if _, err := os.Stat(cur); err != nil {
			t.Fatalf("document-named build was evicted: %v", err)
		}
	})

	t.Run("deleted rows mark every directory stale", func(t *testing.T) {
		// A deleted-status item is pure waste at directory granularity: BOTH
		// its directories reclaim before an unwatched live item's current
		// build — even though the deleted item's fresh progress stamp would
		// otherwise sort it as the most recently watched.
		st, ctx, root := budgetSeed(t, map[string]budgetItem{
			"itm_del": {doc: budgetDoc("complete", "dcur1"), status: "deleted"},
			"itm_cur": {doc: budgetDoc("complete", "aaa1")},
		})
		if _, err := st.PutProgress(ctx, "itm_del", 30, access.System()); err != nil {
			t.Fatalf("PutProgress for deleted item: %v", err)
		}
		cur := budgetBuild(t, root, "itm_cur", "aaa1")
		del1 := budgetBuild(t, root, "itm_del", "zzd1")
		del2 := budgetBuild(t, root, "itm_del", "zzd2")
		sweepBudget(ctx, st, root, dirSize(cur), nil, nil)
		for _, p := range []string{del1, del2} {
			if _, err := os.Stat(p); !os.IsNotExist(err) {
				t.Fatalf("deleted-row directory %s still exists after the budget was met from the stale set (stat err %v)", p, err)
			}
		}
		if _, err := os.Stat(cur); err != nil {
			t.Fatalf("document-named build was evicted: %v", err)
		}
	})

	t.Run("orphan rows mark every directory stale", func(t *testing.T) {
		// No row at all (orphaned by a moved/deleted library file): every
		// directory is reclaimable waste and the budget meets itself from
		// the orphan set alone before touching a current build.
		st, ctx, root := budgetSeed(t, map[string]budgetItem{
			"itm_cur": {doc: budgetDoc("complete", "aaa1")},
		})
		cur := budgetBuild(t, root, "itm_cur", "aaa1")
		orph1 := budgetBuild(t, root, "itm_orph", "zzo1")
		orph2 := budgetBuild(t, root, "itm_orph", "zzo2")
		sweepBudget(ctx, st, root, dirSize(cur), nil, nil)
		for _, p := range []string{orph1, orph2} {
			if _, err := os.Stat(p); !os.IsNotExist(err) {
				t.Fatalf("orphan directory %s still exists after the budget was met from the orphan set (stat err %v)", p, err)
			}
		}
		if _, err := os.Stat(cur); err != nil {
			t.Fatalf("document-named build was evicted: %v", err)
		}
	})
}

// TestSweepRetentionTrashDeleteOnSight pins the already-evicted law for the
// retention pass (alatoic prod defect, 2026-11-10: every boot re-renamed a
// stranded streams build dir, 44b3d67ef54a2033.trash×39, until the rename
// itself failed with ENAMETOOLONG — the WARN-per-boot loop). An
// already-.trash-suffixed directory is ALREADY evicted: the sweep must
// DELETE it on sight, never move it aside again. The distinction matters
// because evictDir's two steps can split — the rename succeeds wherever the
// removal fails — and then every pass that re-encounters the stranded dir
// appends another .trash suffix: unbounded growth on a removal the dir may
// never satisfy. The removal failure is modeled portably with a
// non-writable trash directory (0o555 — RemoveAll cannot unlink its child)
// inside a writable item dir, so the rename-aside succeeds while the
// deletion fails: the exact asymmetry that grew the prod name by one suffix
// per boot. Root cannot model the failure (write bits are invisible to it).
func TestSweepRetentionTrashDeleteOnSight(t *testing.T) {
	// trashSeed seeds one item whose nameless doc (state none) leaves every
	// directory stale, and returns the store, its context, and the artifact
	// root (the retentionSeed shape).
	trashSeed := func(t *testing.T) (*store.Store, context.Context, string, string) {
		t.Helper()
		ctx := context.Background()
		dbPath := filepath.Join(t.TempDir(), "trash.db")
		st, err := store.Open(ctx, dbPath)
		if err != nil {
			t.Fatalf("store.Open: %v", err)
		}
		t.Cleanup(func() { _ = st.Close() })
		libID, err := st.CreateLibrary(ctx, "tv", "/media/trash", "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		raw, err := json.Marshal(map[string]any{
			"streams": map[string]any{"state": "none"},
		})
		if err != nil {
			t.Fatalf("marshal doc: %v", err)
		}
		if err := st.PutItem(ctx, store.Item{
			ID: "itm_tr", ModuleID: "tv", LibraryID: libID, FileID: "itm_tr",
			RelativePath: "itm_tr.mkv", MediaType: "tv",
			Document: raw, SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem: %v", err)
		}
		return st, ctx, filepath.Join(t.TempDir(), "streams"), dbPath
	}

	// trashBuild lays down one aged build directory holding a segment (the
	// retentionBuild shape — a real tree, so a removal must descend).
	trashBuild := func(t *testing.T, root, name string) string {
		t.Helper()
		p := filepath.Join(root, "itm_tr", name)
		if err := os.MkdirAll(p, 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", p, err)
		}
		if err := os.WriteFile(filepath.Join(p, "seg0.ts"), []byte("segment"), 0o644); err != nil {
			t.Fatalf("write segment in %s: %v", p, err)
		}
		old := time.Now().Add(-2 * time.Hour) // comfortably past the 10-minute grace
		if err := os.Chtimes(p, old, old); err != nil {
			t.Fatalf("chtimes %s: %v", p, err)
		}
		return p
	}

	// trashBackdate ages the row anchor past the grace (both anchors stale).
	trashBackdate := func(t *testing.T, dbPath string) {
		t.Helper()
		db, err := sql.Open("sqlite", dbPath)
		if err != nil {
			t.Fatalf("open db for backdate: %v", err)
		}
		defer db.Close()
		stamp := time.Now().Add(-2 * time.Hour).UTC().Format(time.RFC3339Nano)
		res, err := db.ExecContext(context.Background(),
			`UPDATE items SET updated_at = ? WHERE id = ?`, stamp, "itm_tr")
		if err != nil {
			t.Fatalf("backdate updated_at: %v", err)
		}
		if n, _ := res.RowsAffected(); n != 1 {
			t.Fatalf("backdate updated_at: %d rows affected, want 1", n)
		}
	}

	// trashSuffixes returns the .trash-bearing names currently on disk under
	// the item's artifact directory.
	trashSuffixes := func(t *testing.T, root string) []string {
		t.Helper()
		var out []string
		for _, name := range nonces(filepath.Join(root, "itm_tr")) {
			if strings.Contains(name, ".trash") {
				out = append(out, name)
			}
		}
		return out
	}

	t.Run("unremovable stranded trash never gains a suffix across passes", func(t *testing.T) {
		if os.Geteuid() == 0 {
			t.Skip("root ignores directory write bits — the removal failure cannot be modeled")
		}
		st, ctx, root, dbPath := trashSeed(t)
		stranded := trashBuild(t, root, "dead1.trash")
		trashBackdate(t, dbPath)
		// The dir must be movable but unremovable — the prod asymmetry that
		// grew one suffix per boot. Renaming a directory rewrites its ..
		// entry, so it needs write on the dir itself (it stays 0o755); a
		// removal must empty it first, so a 0o555 subdirectory inside makes
		// every RemoveAll fail on the child it cannot unlink.
		blocked := filepath.Join(stranded, "sub")
		if err := os.MkdirAll(blocked, 0o755); err != nil {
			t.Fatalf("mkdir blocked sub: %v", err)
		}
		if err := os.WriteFile(filepath.Join(blocked, "seg1.ts"), []byte("segment"), 0o644); err != nil {
			t.Fatalf("write segment in blocked sub: %v", err)
		}
		if err := os.Chmod(blocked, 0o555); err != nil {
			t.Fatalf("chmod blocked sub: %v", err)
		}
		// The sweep may re-rename the dir before the test ends (that IS the
		// bug), so the cleanup chases the blocked sub by name, not by the
		// original path — TempDir removal must never leak.
		t.Cleanup(func() {
			entries, _ := os.ReadDir(filepath.Join(root, "itm_tr"))
			for _, e := range entries {
				if strings.Contains(e.Name(), "dead1.trash") {
					_ = os.Chmod(filepath.Join(root, "itm_tr", e.Name(), "sub"), 0o755)
				}
			}
		})
		// Laying the blocked subtree refreshed the stranded dir's mtime —
		// re-age it, or the mtime anchor shields it from every pass.
		old := time.Now().Add(-2 * time.Hour)
		if err := os.Chtimes(stranded, old, old); err != nil {
			t.Fatalf("re-age stranded dir: %v", err)
		}

		// Two passes = two boots. Whatever the removal outcome, the dir's
		// name may never grow: at most the original single suffix may remain.
		for pass := 1; pass <= 2; pass++ {
			sweepRetention(ctx, st, root, retentionGrace)
			for _, name := range trashSuffixes(t, root) {
				if name != "dead1.trash" {
					t.Fatalf("pass %d: stranded trash was re-renamed instead of deleted on sight — %q exists (the .trash suffix grew)", pass, name)
				}
			}
		}
	})

	t.Run("deeper stranded suffixes delete on sight", func(t *testing.T) {
		// A dir stranded at depth 2 (already grown once) is deleted outright
		// — no rename-aside, no depth-3 name, no residue of any depth.
		st, ctx, root, dbPath := trashSeed(t)
		trashBuild(t, root, "dead1.trash.trash")
		trashBackdate(t, dbPath)
		sweepRetention(ctx, st, root, retentionGrace)
		if got := trashSuffixes(t, root); len(got) != 0 {
			t.Fatalf("stranded deep trash was re-renamed or left residue, want none, got %v", got)
		}
	})
}
